INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('52921b72-6b6c-40da-88cc-3acfce4fa231', 'rx', 'medium', 'Mr. Khan - DM + HTN', NULL, '{"items":[{"sig":"1 tab BID with meals","drug":"Metformin","strength":"500 mg"},{"sig":"1 tab once daily","drug":"Lisinopril","strength":"10 mg"}],"patient":"Ali Khan, 58M","prescriber":"Dr. Singh"}'::jsonb, ARRAY['Metformin', 'Lisinopril']::text[], '{"age":58,"name":"Ali Khan","weight":82,"allergies":"None"}'::jsonb, '{"drugs":["Metformin","Lisinopril"],"labels":{"Metformin":{"timing":"with food","duration":"ongoing","frequency":"twice daily"},"Lisinopril":{"timing":"morning","duration":"ongoing","frequency":"once daily"}}}'::jsonb, 'Metformin + lisinopril is a common combo for diabetic hypertension.', 'Counsel one drug at a time. Confirm renal function before starting an ACE inhibitor.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('cba2cd08-050e-407a-bbe0-99eea32121f9', 'rx', 'hard', 'Mr. Park - Polypharmacy', NULL, '{"items":[{"sig":"1 tab at bedtime","drug":"Atorvastatin","strength":"20 mg"},{"sig":"1 cap before breakfast","drug":"Omeprazole","strength":"20 mg"},{"sig":"2 puffs PRN","drug":"Salbutamol","strength":"100 mcg"}],"patient":"James Park, 71M","prescriber":"Dr. Cohen"}'::jsonb, ARRAY['Atorvastatin', 'Omeprazole', 'Salbutamol']::text[], '{"age":71,"name":"James Park","allergies":"None","conditions":"COPD, GERD, hyperlipidemia"}'::jsonb, '{"drugs":["Atorvastatin","Omeprazole","Salbutamol"],"labels":{"Omeprazole":{"timing":"morning","duration":"4 weeks","frequency":"once daily"},"Salbutamol":{"timing":"with food","duration":"ongoing","frequency":"as needed"},"Atorvastatin":{"timing":"before sleep","duration":"ongoing","frequency":"once daily"}}}'::jsonb, 'Statin at night, PPI before breakfast, SABA as rescue.', 'Inhalers need technique counseling — never assume the patient knows how to use them.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('6444cfdb-9528-466f-82a3-4b585d2a32e4', 'otc', 'easy', 'Tension headache request', NULL, NULL, ARRAY['Paracetamol']::text[], '{"age":28,"meds":"none","name":"John","symptoms":"mild headache, no fever","allergies":"none"}'::jsonb, '{"complaint":"I have a mild headache since this morning.","questions":[{"q":"Any associated symptoms?","choices":["No, just the headache","Severe stiff neck","Loss of vision","Vomiting blood"],"correct":0},{"q":"Have you taken any meds today?","choices":["Nothing yet","Paracetamol 1g already","Ibuprofen + alcohol","Codeine"],"correct":0}],"correct_dose":"1-2 tabs every 4-6h, max 4g/day","correct_drug":"Paracetamol 500mg","dose_options":["1-2 tabs every 4-6h, max 4g/day","3 tabs every 2h","1 tab once a day","6 tabs at once"],"drug_options":["Paracetamol 500mg","Ibuprofen 400mg","Aspirin 300mg","Codeine"],"advice_options":["Stay hydrated, rest, see a doctor if no improvement in 3 days","Avoid water","Double the dose if pain persists","Take with alcohol"],"correct_advice":"Stay hydrated, rest, see a doctor if no improvement in 3 days"}'::jsonb, 'Paracetamol is safer first-line OTC analgesic.', 'Ask about alcohol use and other paracetamol-containing products.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('6a300398-167a-48aa-be5a-adc84890f57c', 'otc', 'medium', 'Heartburn after dinner', NULL, NULL, ARRAY['Omeprazole']::text[], '{"age":35,"name":"Lina","symptoms":"burning chest after meals 2 weeks","allergies":"none"}'::jsonb, '{"complaint":"I get a burning feeling in my chest after eating.","questions":[{"q":"How long has this been happening?","choices":["2 weeks","Just today","Years","Few hours"],"correct":0},{"q":"Any alarm symptoms?","choices":["No","Black stools","Trouble swallowing","Weight loss"],"correct":0}],"correct_dose":"1 cap daily before breakfast for 14 days","correct_drug":"Omeprazole 20mg","dose_options":["1 cap daily before breakfast for 14 days","3 caps a day with meals","1 cap at bedtime only","As needed only"],"drug_options":["Omeprazole 20mg","Ibuprofen","Amoxicillin","Salbutamol"],"advice_options":["Avoid late meals, elevate head of bed, return if symptoms persist >2 weeks","Eat right before sleeping","Drink coffee with each meal","No lifestyle changes needed"],"correct_advice":"Avoid late meals, elevate head of bed, return if symptoms persist >2 weeks"}'::jsonb, 'Short PPI course for typical reflux is appropriate self-care.', 'Refer red flags: dysphagia, weight loss, GI bleeding.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
