INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('f74d3fca-1285-4bcb-ad4d-cb1fe8404db5', 'hospital', 'medium', 'Post-op DVT prophylaxis review', NULL, NULL, ARRAY['Lisinopril']::text[], '{"age":67,"labs":{"K":4.1,"Hb":11.2,"eGFR":55},"name":"Bed 12","order":"Add lisinopril 10mg PO daily for newly noted HTN","allergies":"none","diagnosis":"Day 2 post hip replacement","current_meds":["Enoxaparin 40mg SC daily","Paracetamol 1g QID","Ibuprofen 400mg TID"]}'::jsonb, '{"drugs":[{"dose":"10","drug":"Lisinopril","route":"oral","frequency":"once daily"}],"remove":["Ibuprofen"],"interactions":[["Lisinopril","Ibuprofen"]]}'::jsonb, 'Stop ibuprofen, start lisinopril at reduced renal dose-monitoring schedule.', 'NSAIDs + ACE inhibitor + reduced renal function = AKI risk. Discontinue NSAID first.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
